using System.Collections;
using System.Diagnostics;
using System.Reflection;
using System.Text;
using Grpc.Tools;
using Microsoft.Build.Utilities;

Console.WriteLine("Hello, World!");
Console.ReadKey();

var pc = new ProtoCompile();

pc.GrpcOutputDir = "obj/Debug/net9.0/Blog";
pc.ToolPath = "/root/.nuget/packages/grpc.tools/2.71.0/tools/linux_arm64/";
pc.ProtoDepDir = "obj/Debug/net9.0/";
pc.OutputDir = "obj/Debug/net9.0/Blog/";
pc.ProtoPath = ["/root/.nuget/packages/grpc.tools/2.71.0/build/native/include", "Protos"];
pc.Generator = "CSharp";
pc.Protobuf = [new TaskItem("Protos/Blog/category.proto")];
pc.BuildEngine = new MyBuildEngine();

Console.WriteLine(pc.GetType().BaseType.GetMethod("ComputePathToTool",BindingFlags.NonPublic|BindingFlags.Instance|BindingFlags.InvokeMethod).Invoke(pc, null));

Console.WriteLine("result: " + pc.Execute());
Console.WriteLine("exitCOde: " + pc.ExitCode);

var responseFileCommands = (string)pc.GetType()
    .GetMethod("GenerateResponseFileCommands", BindingFlags.NonPublic | BindingFlags.Instance | BindingFlags.InvokeMethod).Invoke(pc, null);
responseFileCommands = (string)pc.GetType().BaseType
    .GetMethod("AdjustCommandsForOperatingSystem", BindingFlags.NonPublic | BindingFlags.Instance | BindingFlags.InvokeMethod,
        new[] { typeof(string) }).Invoke(pc, new object[] { responseFileCommands });

string responseFileSwitch;
string responseFile;
if (!String.IsNullOrEmpty(responseFileCommands))
{
    var directory = Path.GetTempPath();
    Directory.CreateDirectory(directory);

    responseFile = Path.Combine(directory, string.Format("tmp{0}{1}", Guid.NewGuid().ToString("N"), ".rsp"));
    File.WriteAllText(responseFile, String.Empty);
    const int DefaultFileStreamBufferSize = 4096;
    FileMode mode = FileMode.Create;
    Stream fileStream = new FileStream(responseFile, mode, FileAccess.Write, FileShare.Read, DefaultFileStreamBufferSize,
        FileOptions.SequentialScan);

    // Use the encoding specified by the overridable ResponseFileEncoding property
    using (StreamWriter responseFileStream = new StreamWriter(fileStream, Encoding.UTF8))
    {
        responseFileStream.Write(responseFileCommands);
    }

    responseFileSwitch = "@\"" + responseFile + "\"";
}
var proc = new Process();
ProcessStartInfo startInfo = new ProcessStartInfo("/root/.nuget/packages/grpc.tools/2.71.0/tools/linux_arm64/protoc",
    "--csharp_out=obj/Debug/net9.0/Blog --proto_path=/root/.nuget/packages/grpc.tools/2.71.0/build/native/include --proto_path=Protos --dependency_out=obj/Debug/net9.0/d28e7ea91bb82de6_category.protodep --error_format=msvs Protos/Blog/category.proto");
startInfo.CreateNoWindow = true;
startInfo.UseShellExecute = false;
startInfo.RedirectStandardError = true;
startInfo.RedirectStandardOutput = true;
startInfo.StandardErrorEncoding = Encoding.UTF8;
startInfo.StandardOutputEncoding = Encoding.UTF8;
var _standardErrorData = new Queue();
var _standardOutputData = new Queue();

var _standardErrorDataAvailable = new ManualResetEvent(false);
var _standardOutputDataAvailable = new ManualResetEvent(false);

var _toolExited = new ManualResetEvent(false);
var _toolTimeoutExpired = new ManualResetEvent(false);

var _eventsDisposed = false;

void ReceiveExitNotification(object sender, EventArgs e)
{
    if (!_eventsDisposed)
    {
        _toolExited.Set();
    }
}

void ReceiveStandardErrorData(object sender, DataReceivedEventArgs e)
{
    ReceiveStandardErrorOrOutputData(e, _standardErrorData, _standardErrorDataAvailable);
}

void ReceiveStandardOutputData(object sender, DataReceivedEventArgs e)
{
    ReceiveStandardErrorOrOutputData(e, _standardOutputData, _standardOutputDataAvailable);
}

void ReceiveStandardErrorOrOutputData(
    DataReceivedEventArgs e,
    Queue dataQueue,
    ManualResetEvent dataAvailableSignal)
{
    if (e.Data != null)
    {
        lock (dataQueue.SyncRoot)
        {
            dataQueue.Enqueue(e.Data);

            if (!_eventsDisposed)
            {
                dataAvailableSignal.Set();
            }
        }
    }
}

proc.StartInfo = startInfo;
proc.EnableRaisingEvents = true;
proc.Exited += new EventHandler(ReceiveExitNotification);
proc.ErrorDataReceived += new DataReceivedEventHandler(ReceiveStandardErrorData);
proc.OutputDataReceived += new DataReceivedEventHandler(ReceiveStandardOutputData);

proc.Start();
proc.BeginErrorReadLine();
proc.BeginOutputReadLine();
proc.WaitForExit();

void LogMessagesFromStandardErrorOrOutput(
    Queue dataQueue,
    ManualResetEvent dataAvailableSignal)
{
    while (dataQueue.Count > 0)
    {
        string errorOrOutMessage = dataQueue.Dequeue() as String;

        Console.WriteLine(errorOrOutMessage);
    }
    dataAvailableSignal.Reset();
}

LogMessagesFromStandardErrorOrOutput(_standardErrorData, _standardErrorDataAvailable);
LogMessagesFromStandardErrorOrOutput(_standardOutputData, _standardOutputDataAvailable);
Console.WriteLine("exitCode: " + proc.ExitCode);
